-- restamp_universe_guid7_20260615.sql
-- ───────────────────────────────────────────────────────────────────────────
-- ONE-TIME, DEV-DB-ONLY correction: the first universe migrations seeded the
-- sentinel ids 11111111…/22222222…/99999999…. We switched the well-known ids to
-- UUIDv7 (matching every other Id in the app). This re-stamps the EXISTING data
-- + history + the Universe PK to the new v7 ids. A FRESH database never needs
-- this (its seed migrations already use the v7 ids), so this file is NOT added
-- to the ApplyMigrations list — run it once by hand on a pre-v7 dev DB.
--   GLMZ:    11111111-… -> 0197e9c9-0001-7000-8000-000000000001
--   Fantasy: 22222222-… -> 0197e9c9-0002-7000-8000-000000000002
--   Shared:  99999999-… -> 0197e9c9-0099-7000-8000-000000000099
-- Run under QUOTED_IDENTIFIER ON (sqlcmd -I). Idempotent (no old ids => no-ops).
-- ───────────────────────────────────────────────────────────────────────────

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

-- Reusable mapping expression: CASE UniverseId WHEN <old> THEN <new> ... ELSE UniverseId END
-- (written inline per table below).

-- ── Temporal tables: OFF, re-stamp current + _History, ON ───────────────────
-- Entities
ALTER TABLE dbo.Entities SET (SYSTEM_VERSIONING = OFF);
GO
UPDATE dbo.Entities         SET UniverseId = CASE UniverseId WHEN '11111111-1111-1111-1111-111111111111' THEN '0197e9c9-0001-7000-8000-000000000001' WHEN '22222222-2222-2222-2222-222222222222' THEN '0197e9c9-0002-7000-8000-000000000002' WHEN '99999999-9999-9999-9999-999999999999' THEN '0197e9c9-0099-7000-8000-000000000099' ELSE UniverseId END;
UPDATE dbo.Entities_History SET UniverseId = CASE UniverseId WHEN '11111111-1111-1111-1111-111111111111' THEN '0197e9c9-0001-7000-8000-000000000001' WHEN '22222222-2222-2222-2222-222222222222' THEN '0197e9c9-0002-7000-8000-000000000002' WHEN '99999999-9999-9999-9999-999999999999' THEN '0197e9c9-0099-7000-8000-000000000099' ELSE UniverseId END;
ALTER TABLE dbo.Entities SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = dbo.Entities_History, DATA_CONSISTENCY_CHECK = OFF));
GO
