UPDATE dbo.Strands_History SET UniverseId = CASE UniverseId WHEN '11111111-1111-1111-1111-111111111111' THEN '0197e9c9-0001-7000-8000-000000000001' WHEN '22222222-2222-2222-2222-222222222222' THEN '0197e9c9-0002-7000-8000-000000000002' WHEN '99999999-9999-9999-9999-999999999999' THEN '0197e9c9-0099-7000-8000-000000000099' ELSE UniverseId END;
ALTER TABLE dbo.Strands SET (SYSTEM_VERSIONING = ON (HISTORY_TABLE = dbo.Strands_History, DATA_CONSISTENCY_CHECK = OFF));
