-- ── The Universe table's own PK ─────────────────────────────────────────────
UPDATE dbo.Universe SET Id = CASE Id WHEN '11111111-1111-1111-1111-111111111111' THEN '0197e9c9-0001-7000-8000-000000000001' WHEN '22222222-2222-2222-2222-222222222222' THEN '0197e9c9-0002-7000-8000-000000000002' ELSE Id END
    WHERE Id IN ('11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222');
GO
